import{_ as d,C as t,o as y,c as x,j as a,a as p,E as n,a2 as e,w as l}from"./chunks/framework.B-bxTAy7.js";const C=JSON.parse('{"title":"20 · PLC 与梯形图","description":"PLC 的循环扫描工作方式；梯形图与逻辑式的互换规则；启保停、双线圈禁忌、停止按钮的故障导向安全接法，配四道例题。","frontmatter":{"title":"20 · PLC 与梯形图","description":"PLC 的循环扫描工作方式；梯形图与逻辑式的互换规则；启保停、双线圈禁忌、停止按钮的故障导向安全接法，配四道例题。"},"headers":[],"relativePath":"ee/07-control/plc.md","filePath":"ee/07-control/plc.md","lastUpdated":1792474335000}'),u={name:"ee/07-control/plc.md"},b={class:"tip custom-block"},w={class:"tip custom-block"};function k(v,s,M,T,_,P){const i=t("Meta"),r=t("Prereq"),c=t("LadderDemo"),o=t("DemoBox"),h=t("WavePreset"),g=t("FigBox"),m=t("CircuitFig");return y(),x("div",null,[s[10]||(s[10]=a("h1",{id:"_20-·-plc-与梯形图",tabindex:"-1"},[p("20 · PLC 与梯形图 "),a("a",{class:"header-anchor",href:"#_20-·-plc-与梯形图","aria-label":'Permalink to "20 · PLC 与梯形图"'},"​")],-1)),n(i,{time:"25 min",level:"了解",note:"重点：扫描周期、梯形图与逻辑式的互换、双线圈禁忌"}),s[11]||(s[11]=a("p",null,[a("strong",null,"这一页要解决什么"),p("：上一章的自锁、互锁靠硬接线，改一个逻辑就得重新拉线。这一页把同一套逻辑搬进 "),a("strong",null,"PLC"),p("（Programmable Logic Controller，可编程逻辑控制器：面向工业开关量控制的专用计算机）。读完你应该能：说清 PLC 一个扫描周期里发生什么、把梯形图和逻辑式互相翻译、解释双线圈为什么被禁止、并按「故障导向安全」的规则接停止按钮。")],-1)),a("div",b,[s[6]||(s[6]=a("p",{class:"custom-block-title"},"读这页之前",-1)),a("ul",null,[a("li",null,[s[0]||(s[0]=a("strong",null,"需要会",-1)),s[1]||(s[1]=p("：",-1)),s[2]||(s[2]=a("a",{href:"./relay"},"第 19 章 · 继电接触器控制",-1)),s[3]||(s[3]=p(" 的自锁与互锁、逻辑代数基础（",-1)),n(r,{id:"boolean-algebra"}),s[4]||(s[4]=p("）。",-1))]),s[5]||(s[5]=e('<li><strong>这一页用到的记号</strong>：I（输入位）、Q（输出位）、M（内部中间位）、T（定时器）、C（计数器）——PLC 里的「位」就是一个 0/1 变量，触点是读位，线圈是写位。</li><li><strong>符号与约定</strong>：逻辑式记号（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>⋅</mo></mrow><annotation encoding="application/x-tex">\\cdot</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord">⋅</span></span></span></span> 与、<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>+</mo></mrow><annotation encoding="application/x-tex">+</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">+</span></span></span></span> 或、上划线非）见<a href="./../../guide/notation">符号与约定</a>。</li><li><strong>一个词先给一句话</strong>：<strong>梯形图</strong>（ladder diagram：把触点画成横档、母线画成两根竖轨的编程语言）长得像继电器电路图，是 PLC 最常用的编程方式。</li>',3))])]),s[12]||(s[12]=e(`<p>上一章的自锁电路一旦要加一个延时、改一个联锁，就得拆线重接。工厂里这类「改逻辑」每个月都有，于是一台机器代替了整面继电器屏：PLC 用程序实现同样的触点逻辑，梯形图写起来还像继电器图，改起来却只需改几行代码。但「像继电器」只是长相——PLC 里面没有电流，只有被一遍遍重复执行的计算。这一页就讲这个「像而不一样」到底差在哪。</p><h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ol><li>PLC 是工业控制计算机，<strong>循环扫描</strong>工作：输入采样 → 执行程序 → 输出刷新，周而复始</li><li>梯形图长得像继电器电路，但<strong>里面没有电流</strong>，只有逻辑运算——「能流」只是形象说法</li><li>梯形图与逻辑式一一对应：<strong>串联 = 与，并联 = 或，常闭 = 取反</strong>；这是考试的基本功</li><li>启保停的梯形图和继电器电路<strong>长得完全一样</strong>，但「自锁」的含义变了：继电器里是触点闭合，PLC 里是输出位为 1</li><li><strong>同一线圈在一个程序里只能出现一次</strong>（双线圈禁忌），而触点可以无限次引用</li><li>停止按钮要<strong>故障导向安全</strong>：硬件接常闭，程序里当「条件」串联</li></ol><h2 id="工作原理-循环扫描" tabindex="-1">工作原理：循环扫描 <a class="header-anchor" href="#工作原理-循环扫描" aria-label="Permalink to &quot;工作原理：循环扫描&quot;">​</a></h2><p>这一节回答一个问题：PLC 把程序从头到尾跑一遍，中间到底发生了什么——理解了它，响应延迟和双线圈两个坑就都推得出来。</p><p>PLC 加电后不停重复三件事：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>每个扫描周期：</span></span>
<span class="line"><span>  ① 输入采样  读所有输入端子 → 输入映像寄存器</span></span>
<span class="line"><span>  ② 执行程序  按梯形图从上到下、从左到右做逻辑运算 → 输出映像寄存器</span></span>
<span class="line"><span>  ③ 输出刷新  把输出映像的值送到输出端子 → 驱动接触器、电磁阀、指示灯</span></span></code></pre></div><p>关键在「映像」两个字：<strong>程序不直接读端子，也不直接写端子</strong>，读写的都是映像寄存器。输入的变化要等下一次采样才被看见，输出的变化要等刷新时刻才生效——这就是响应延迟的来源。</p>`,8)),n(o,{title:"PLC 梯形图交互演示",hint:"点梯形图里的输入触点切换通断。注意它不会立刻生效——看下面的扫描阶段指示，输入要等「采样」、输出要等「刷新」。"},{default:l(()=>[n(c,{mode:"「latch」"})]),_:1}),n(g,{caption:"扫描周期时序：输入在周期「中间」跳变（1.5），采样要等下一个周期开始（2.0），输出刷新又晚半个周期（2.85）"},{default:l(()=>[n(h,{kind:"scancycle"})]),_:1}),s[13]||(s[13]=e('<div class="tip custom-block"><p class="custom-block-title">扫描周期带来两个直接后果</p><ol><li><strong>响应延迟</strong>：输入变化到输出响应的延迟在 1~2 个扫描周期之间（见例 2）。周期越短响应越快，但周期受程序长短限制——这就是为什么「程序写得简洁」有工程意义。</li><li><strong>双线圈输出会互相覆盖</strong>：因为输出最终由映像寄存器里最后一次写入的值决定（见例 3）。</li></ol></div><p>扫描机制立住了，接下来看程序本身长什么样——先认梯形图的五个符号。</p><h2 id="梯形图符号" tabindex="-1">梯形图符号 <a class="header-anchor" href="#梯形图符号" aria-label="Permalink to &quot;梯形图符号&quot;">​</a></h2><p>这一节只做认字：五个梯形图元素各是什么、读成什么逻辑。</p><table tabindex="0"><thead><tr><th>元素</th><th>画法</th><th>含义</th></tr></thead><tbody><tr><td>常开触点</td><td>`─</td><td></td></tr><tr><td>常闭触点</td><td>`─</td><td>/</td></tr><tr><td>线圈</td><td><code>─( )─</code></td><td>逻辑结果写入输出位</td></tr><tr><td>定时器</td><td><code>─[TON T0 100]─</code></td><td>延时接通</td></tr><tr><td>计数器</td><td><code>─[CTU C0 5]─</code></td><td>加计数</td></tr></tbody></table><p>左母线（电源正）→ 触点组合 → 线圈 → 右母线（电源负）。梯形图是「横着的一条条支路」，每条支路是一个逻辑等式。</p><p>一条典型梯级长这样（两个触点串联驱动一个线圈）：</p>',7)),n(m,{kind:"ladder",title:"PLC 梯形图：左母线 → 触点串联 → 线圈 → 右母线"}),s[14]||(s[14]=e('<div class="tip custom-block"><p class="custom-block-title">心智模型：梯形图 = 软继电器 + 扫描，不是实物接线</p><p>看梯形图先立一个模型：左右母线不是真的电源，支路里没有电流，只有<strong>逻辑</strong>——「能流」只是形象说法。它是被 CPU <strong>从上到下、从左到右扫描执行</strong>的一段程序：触点读的是「位」的 0/1，线圈是把运算结果写进「位」。所以读一条梯级，就当读一个布尔等式，别去追电流路径——这也是为什么「双线圈」会互相覆盖（见例 3）。</p></div><h2 id="梯形图-↔-逻辑式-考试基本功" tabindex="-1">梯形图 ↔ 逻辑式（考试基本功） <a class="header-anchor" href="#梯形图-↔-逻辑式-考试基本功" aria-label="Permalink to &quot;梯形图 ↔ 逻辑式（考试基本功）&quot;">​</a></h2><p>这一节给一条固定通道：任何梯形图都能机械地翻译成逻辑式，反过来也一样——这是本页所有例题的共同工具。</p><table tabindex="0"><thead><tr><th>梯形图结构</th><th>逻辑式</th></tr></thead><tbody><tr><td>两个触点串联</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo>=</mo><mi>A</mi><mo>⋅</mo><mi>B</mi></mrow><annotation encoding="application/x-tex">Q = A \\cdot B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span></td></tr><tr><td>两个触点并联</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo>=</mo><mi>A</mi><mo>+</mo><mi>B</mi></mrow><annotation encoding="application/x-tex">Q = A + B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">A</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span></td></tr><tr><td>常闭触点 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span></td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mover accent="true"><mi>A</mi><mo>ˉ</mo></mover></mrow><annotation encoding="application/x-tex">\\bar{A}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8201em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8201em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">A</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1111em;"><span class="mord">ˉ</span></span></span></span></span></span></span></span></span></span></td></tr><tr><td>启保停</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo>=</mo><mo stretchy="false">(</mo><mi>A</mi><mo>+</mo><mi>Q</mi><mo stretchy="false">)</mo><mo>⋅</mo><mover accent="true"><mi>B</mi><mo>ˉ</mo></mover></mrow><annotation encoding="application/x-tex">Q = (A + Q)\\cdot \\bar{B}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal">A</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">Q</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8201em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8201em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">ˉ</span></span></span></span></span></span></span></span></span></span>（<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal">A</span></span></span></span> 起动、<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>B</mi></mrow><annotation encoding="application/x-tex">B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span></span></span> 停止）</td></tr><tr><td>正反转（带互锁）</td><td><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>Q</mi><mn>0</mn></msub><mo>=</mo><mo stretchy="false">(</mo><msub><mi>A</mi><mn>0</mn></msub><mo>+</mo><msub><mi>Q</mi><mn>0</mn></msub><mo stretchy="false">)</mo><mo>⋅</mo><mover accent="true"><mi>B</mi><mo>ˉ</mo></mover><mo>⋅</mo><mover accent="true"><msub><mi>Q</mi><mn>1</mn></msub><mo>ˉ</mo></mover></mrow><annotation encoding="application/x-tex">Q_0 = (A_0 + Q_0)\\cdot\\bar B\\cdot \\bar{Q_1}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal">A</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8201em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8201em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal" style="margin-right:0.0502em;">B</span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.1667em;"><span class="mord">ˉ</span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0145em;vertical-align:-0.1944em;"></span><span class="mord accent"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8201em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal">Q</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span><span style="top:-3.2523em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.25em;"><span class="mord">ˉ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.1944em;"><span></span></span></span></span></span></span></span></span></td></tr></tbody></table><p><strong>转换规则</strong>：从左母线开始，遇到串联就「乘」，遇到并联就「加」，遇到常闭就「取反」，一直推到线圈。练三五遍就能条件反射。</p><p><strong>转换规则</strong>：从左母线开始，遇到串联就「乘」，遇到并联就「加」，遇到常闭就「取反」，一直推到线圈。练三五遍就能条件反射。</p><p>互译规则在手，就能把上一章的继电器电路直接搬进 PLC——搬的时候每个器件对应 PLC 里什么东西，见下一节。</p><h2 id="从继电器电路改造" tabindex="-1">从继电器电路改造 <a class="header-anchor" href="#从继电器电路改造" aria-label="Permalink to &quot;从继电器电路改造&quot;">​</a></h2><p>这一节把上一章的零件逐个映射到 PLC 的 I/Q/M/T，并顺带解决「停止按钮接常开还是常闭」这个安全关键问题。</p><p><a href="./relay">第 19 章 · 继电接触器控制</a>那张继电控制图，改造成 PLC 只要重画控制电路那半边：</p><table tabindex="0"><thead><tr><th>继电器电路里的</th><th>PLC 里的</th></tr></thead><tbody><tr><td>按钮、行程开关、传感器</td><td>输入点 I</td></tr><tr><td>接触器线圈、电磁阀、指示灯</td><td>输出点 Q</td></tr><tr><td>中间继电器的触点逻辑</td><td>内部位 M</td></tr><tr><td>时间继电器</td><td>定时器 T</td></tr><tr><td>热继电器常闭触点</td><td>输入点（或保留在硬件回路做后备保护）</td></tr><tr><td>自锁/互锁触点</td><td>输出位的常开/常闭触点（<strong>软触点，可无限次使用</strong>）</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">停止按钮接常开还是常闭</p><p><strong>硬件接常闭，程序里当「条件」用</strong>（梯形图里画成常开触点 <code>─| |─</code>，逻辑式里直接串联 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>I</mi><mn>0.1</mn></mrow><annotation encoding="application/x-tex">I0.1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mord">0.1</span></span></span></span>）。</p><p>原因：这样接线时，按钮按下 → 回路断开 → <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>I</mi><mn>0.1</mn><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">I0.1 = 0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mord">0.1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> → 程序停机。而如果<strong>电线断线</strong>（故障），<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>I</mi><mn>0.1</mn></mrow><annotation encoding="application/x-tex">I0.1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mord">0.1</span></span></span></span> 同样变 0，电机同样停机——这就是「故障导向安全」。反过来若接常开，断线时程序以为「没按停止」，电机会继续转，很危险。</p></div><p>器件映射完、安全规则立住了。例题之前，先扫一眼指令表——知道 PLC 有哪些积木，读例题才不卡。</p><h2 id="常用指令" tabindex="-1">常用指令 <a class="header-anchor" href="#常用指令" aria-label="Permalink to &quot;常用指令&quot;">​</a></h2><p>这一节是速查表，不用背；例题里用到 TON 时回来看一眼即可。</p><table tabindex="0"><thead><tr><th>类别</th><th>指令</th><th>说明</th></tr></thead><tbody><tr><td>位逻辑</td><td>LD / LDN / A / AN / O / ON / =</td><td>取、与、或、输出</td></tr><tr><td>定时</td><td>TON（接通延时）、TOF（断开延时）、TP（脉冲）</td><td>PT 是设定值</td></tr><tr><td>计数</td><td>CTU / CTD / CTUD</td><td>计到设定值置位</td></tr><tr><td>数据处理</td><td>传送 MOV、比较、运算、移位</td><td>—</td></tr><tr><td>边沿检测</td><td>EU / ED</td><td>只在状态变化的那一个周期动作一次</td></tr></tbody></table><p>指令认全了，开始做题——四道题从互译到组合，覆盖本页全部要点。</p><h2 id="例题" tabindex="-1">例题 <a class="header-anchor" href="#例题" aria-label="Permalink to &quot;例题&quot;">​</a></h2><p>四道题按「翻译 → 计时 → 辨析 → 组合」排，每题先看「先想什么」。</p>',19)),a("div",w,[s[7]||(s[7]=a("p",{class:"custom-block-title"},"例 1 · 梯形图转逻辑式",-1)),s[8]||(s[8]=a("p",null,"写出下图梯形图的逻辑表达式，并说明它实现什么功能。",-1)),n(m,{kind:"ladder",title:"例 1 的梯形图：I0.0 与自锁触点 Q0.0 并联，串常闭 I0.1，驱动 Q0.0",note:"先找线圈，再倒推它的触点组合：两条并联支路（I0.0 与 Q0.0 常开）共同串联一个常闭触点 I0.1。"}),s[9]||(s[9]=e(`<p><strong>先想什么</strong>：读梯形图别追「电流」，按固定动作走——先找到线圈，再从左母线倒推线圈的触点组合：并联是 +、串联是 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>⋅</mo></mrow><annotation encoding="application/x-tex">\\cdot</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4445em;"></span><span class="mord">⋅</span></span></span></span>、常闭取反。翻译完再看这个式子像谁。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>  I0.0   Q0.0</span></span>
<span class="line"><span>──| |──┬──| |──┬──|/|────( )──</span></span>
<span class="line"><span>       │       │   I0.1  Q0.0</span></span>
<span class="line"><span>       └───────┘</span></span></code></pre></div><p><strong>解</strong>：两条并联支路（I0.0 与 Q0.0 常开）串联 I0.1 常闭，驱动 Q0.0 线圈：</p><span class="katex-display"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML" display="block"><semantics><mrow><mi>Q</mi><mn>0.0</mn><mo>=</mo><mo stretchy="false">(</mo><mi>I</mi><mn>0.0</mn><mo>+</mo><mi>Q</mi><mn>0.0</mn><mo stretchy="false">)</mo><mo>⋅</mo><mover accent="true"><mrow><mi>I</mi><mn>0.1</mn></mrow><mo stretchy="true">‾</mo></mover></mrow><annotation encoding="application/x-tex">Q0.0 = (I0.0 + Q0.0)\\cdot \\overline{I0.1} </annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mord">0.0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mord">0.0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">Q</span><span class="mord">0.0</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8833em;"></span><span class="mord overline"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.8833em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mord">0.1</span></span></span><span style="top:-3.8033em;"><span class="pstrut" style="height:3em;"></span><span class="overline-line" style="border-bottom-width:0.04em;"></span></span></span></span></span></span></span></span></span></span><p>这正是<strong>启保停</strong>：I0.0 是起动按钮（按一下即松开，靠 Q0.0 自己的常开触点续上），I0.1 是停止按钮（常闭，程序里取反后串联）。与<a href="./relay">第 19 章 · 继电接触器控制</a>的继电器电路完全同构——只是这里的 Q0.0 触点不占物理端子，可以随意使用。</p><p><strong>验算</strong>：代入两个边界状态——按住 I0.0、未按 I0.1：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo>=</mo><mo stretchy="false">(</mo><mn>1</mn><mo>+</mo><mn>0</mn><mo stretchy="false">)</mo><mo>⋅</mo><mn>1</mn><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">Q=(1+0)\\cdot 1=1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">0</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> ✓ 起动；松开 I0.0：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo>=</mo><mo stretchy="false">(</mo><mn>0</mn><mo>+</mo><mn>1</mn><mo stretchy="false">)</mo><mo>⋅</mo><mn>1</mn><mo>=</mo><mn>1</mn></mrow><annotation encoding="application/x-tex">Q=(0+1)\\cdot 1=1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span> ✓ 保持；按 I0.1：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>Q</mi><mo>=</mo><mo stretchy="false">(</mo><mn>0</mn><mo>+</mo><mn>1</mn><mo stretchy="false">)</mo><mo>⋅</mo><mn>0</mn><mo>=</mo><mn>0</mn></mrow><annotation encoding="application/x-tex">Q=(0+1)\\cdot 0=0</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8778em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">Q</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">1</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">⋅</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> ✓ 停止。自锁、停止全部吻合。</p>`,6))]),s[15]||(s[15]=e(`<div class="tip custom-block"><p class="custom-block-title">例 2 · 扫描周期与响应延迟</p><p>某 PLC 扫描周期 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mo>=</mo><mn>100</mn></mrow><annotation encoding="application/x-tex">T = 100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">100</span></span></span></span> ms，其中输入采样占前 5 ms，输出刷新在第 90~95 ms。输入 I0.0 在<strong>执行程序阶段中途</strong>（第 6 ms）发生变化，输出 Q0.0 什么时候响应？</p><p><strong>先想什么</strong>：这是把扫描三阶段当时间轴用的题。关键动作只有两步：找<strong>下一次采样</strong>时刻（输入映像何时更新），再找那之后的<strong>下一次刷新</strong>时刻（输出何时生效），两者相减就是延迟。</p><ol><li><strong>采样时机</strong>：变化发生在第 6 ms，本周期的采样（0~5 ms）已经过去了。所以要等<strong>下一个周期</strong>的采样，即第 100 ms 时 I0.0 的新状态才进入输入映像寄存器。等待时间 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo><mn>100</mn><mo>−</mo><mn>6</mn><mo>=</mo><mn>94</mn></mrow><annotation encoding="application/x-tex">= 100 - 6 = 94</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">100</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">94</span></span></span></span> ms。<em>（为什么不在本周期补采：扫描纪律是「程序执行期间输入映像冻结」，中途改读会让同一段程序前后看到不一致的世界。）</em></li><li><strong>刷新时机</strong>：下一周期执行程序、刷新输出发生在第 90~95 ms（即第 190 ms 时刻），Q0.0 此刻才真正改变。从输入变化算起共延迟 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>190</mn><mo>−</mo><mn>6</mn><mo>=</mo><mn>184</mn></mrow><annotation encoding="application/x-tex">190 - 6 = 184</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">190</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">184</span></span></span></span> ms <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mn>1.84</mn><mtext> </mtext><mi>T</mi></mrow><annotation encoding="application/x-tex">\\approx 1.84\\,T</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">1.84</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span>。<em>（为什么不是刷新点 90 ms：执行程序读的还是刷新前的输出映像，必须等刷新完成才送到端子。）</em></li></ol><p>另一种极端：若输入在第 99 ms 变化（采样前 1 ms），则第 100 ms 就被采入，输出在第 190 ms 刷新，延迟仅 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>91</mn></mrow><annotation encoding="application/x-tex">91</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">91</span></span></span></span> ms <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mn>0.91</mn><mtext> </mtext><mi>T</mi></mrow><annotation encoding="application/x-tex">\\approx 0.91\\,T</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord">0.91</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.1389em;">T</span></span></span></span>。</p><p><strong>验算</strong>：延迟 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>=</mo></mrow><annotation encoding="application/x-tex">=</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.3669em;"></span><span class="mrel">=</span></span></span></span> 采样等待 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>+</mo></mrow><annotation encoding="application/x-tex">+</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord">+</span></span></span></span> 执行等待 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mo>≈</mo><mn>94</mn><mo>+</mo><mn>90</mn><mo>=</mo><mn>184</mn></mrow><annotation encoding="application/x-tex">\\approx 94 + 90 = 184</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4831em;"></span><span class="mrel">≈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">94</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">90</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">184</span></span></span></span> ms，与直接相减 <span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>190</mn><mo>−</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">190-6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">190</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">6</span></span></span></span> 一致 ✓；两个极端（0.91 T 与 1.84 T）都落在「1~2 个周期」的结论区间内 ✓。</p><p><strong>结论</strong>：响应延迟在 <strong>1~2 个扫描周期</strong>之间。工程上按「一个周期」估算；对响应速度有要求的场合（如限位急停），要么缩短扫描周期，要么把最关键的信号接进<strong>高速输入/中断</strong>，不能指望主循环。</p></div><div class="tip custom-block"><p class="custom-block-title">例 3 · 双线圈为什么是禁忌</p><p>程序中同一个输出线圈 Q0.0 在两个地方各出现一次：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>支路1：I0.0 ──| |──────────(Q0.0)──</span></span>
<span class="line"><span>支路2：I0.1 ──| |──────────(Q0.0)──</span></span></code></pre></div><p>I0.0 = 1、I0.1 = 0 时，Q0.0 是什么？</p><p><strong>先想什么</strong>：直觉答案「两条支路并联，Q0.0 = 1」来自继电器思维。这题考的正是那个模型的失效——PLC 是<strong>串行</strong>执行的，同一个线圈被写了两次，后一次必然覆盖前一次，问题变成「最后写的是哪条支路」。</p><p><strong>解</strong>：<strong>Q0.0 = 0</strong>。</p><p>因为扫描是「从上到下」顺序执行的：支路 1 执行时算得 Q0.0 = 1 写进输出映像；执行到支路 2 时又算得 Q0.0 = 0，<strong>把前面的结果覆盖掉</strong>。刷新时送到端子的是最后写入的值——支路 1 的逻辑等于白写。</p><p><strong>验算</strong>：把执行顺序逐步列表——扫描到支路 1：输出映像 Q0.0 ← 1；扫描到支路 2：输出映像 Q0.0 ← 0；刷新：端子得到 0 ✓（与串行覆盖推理一致）。</p><p>这与继电器电路有本质区别：继电器电路里两个支路是真正的并联（物理上同时存在），而 PLC 是串行执行。<strong>结论：一个线圈在程序里只允许出现一次</strong>；想实现「或」逻辑，就把两个条件并联到同一支路里，或者用内部位 M 中转。</p><p>触点则相反：<strong>常开/常闭触点可以无限次引用</strong>，因为它们只是「读」位状态，不产生写入冲突。</p></div><div class="tip custom-block"><p class="custom-block-title">例 4 · 定时器延时起动</p><p>要求：按下 I0.0 后<strong>延时 10 s</strong> 才接通 Q0.0；松开 I0.0 立即停止。设 TON 定时器时基为 100 ms，写出梯形图结构和 PT 值。</p><p><strong>先想什么</strong>：拆需求——「延时接通」正是 TON（接通延时定时器，条件满足后开始计时、计满才闭合触点）的定义，所以选型不用犹豫；剩下两件事：定时器挂在哪个条件上（I0.0，因为松开要立即停 → 计时中断 → 触点断开），以及 PT 怎么从 10 s 换算成计数个数。</p><p><strong>解</strong>：TON 是「接通延时」定时器——条件一满足就开始计时，计到 PT 才把触点闭合。所以：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>I0.0 ──| |────[TON  T0  PT=100]──</span></span>
<span class="line"><span>                    T0 常开 ──| |────────( Q0.0 )──</span></span></code></pre></div><p>PT 的换算：时基 100 ms × 100 = 10 000 ms = <strong>10 s</strong>，所以 <strong>PT = 100</strong>。</p><p>两个容易错的地方：</p><ul><li><strong>TON 计时期间触点还没闭合</strong>，Q0.0 不会动作；计时中断（条件消失）时定时器<strong>当前值清零</strong>，下次重新从 0 计</li><li>若要「延时断开」，得用 TOF 或用「停止后启动另一个定时器」的写法——TON 本身做不到</li></ul><p><strong>验算</strong>：PT 换算倒推：<span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mn>100</mn><mo>×</mo><mn>100</mn><mtext> ms</mtext><mo>=</mo><mn>10</mn><mtext> s</mtext></mrow><annotation encoding="application/x-tex">100\\times100\\ \\text{ms}=10\\ \\text{s}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7278em;vertical-align:-0.0833em;"></span><span class="mord">100</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">100</span><span class="mspace"> </span><span class="mord text"><span class="mord">ms</span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">10</span><span class="mspace"> </span><span class="mord text"><span class="mord">s</span></span></span></span></span> ✓；行为核对——按住 I0.0 满足 10 s 后 Q0.0 = 1，第 9.9 s 松开则计时清零、Q0.0 保持 0，与「松开立即停止」的要求一致 ✓。</p></div><p>例题做完，最后看一台真实的老机床怎么从继电器柜改成 PLC 控制——把本页所有概念串起来。</p><h2 id="工程实例-用-plc-改造一台老机床" tabindex="-1">工程实例：用 PLC 改造一台老机床 <a class="header-anchor" href="#工程实例-用-plc-改造一台老机床" aria-label="Permalink to &quot;工程实例：用 PLC 改造一台老机床&quot;">​</a></h2><p>这一节是操作清单式的收尾：看改造五步里分别用了本页的哪个知识点。</p><p>老设备是继电接触器控制，改造步骤：</p><ol><li><strong>清点 I/O</strong>：数输入（起动、停止、正转、反转、限位 ×3、热继电器、急停 ≈ 8 点）和输出（正转线圈、反转线圈、指示灯 ×4 ≈ 6 点），选 16 点输入 / 16 点输出的小型 PLC（点数留 30% 裕量）</li><li><strong>分配地址</strong>：把每个器件写成 I/O 分配表，这是程序的「图纸」</li><li><strong>翻译控制电路</strong>：主电路几乎不动（接触器、热继电器、电机原样保留），只把控制电路的硬接线换成梯形图；<strong>热继电器仍接在硬件回路里</strong>作后备保护——程序不能是唯一的安全屏障</li><li><strong>急停必须硬接线</strong>：急停按钮直接串在接触器线圈的电源回路里，不经过 PLC 程序。<strong>程序会死机，硬件不会</strong></li><li><strong>调试</strong>：先单独调每个支路（点动），再联调；用「强制」功能模拟输入，避免反复按按钮</li></ol><p>改造的收益不只是省电线：改工艺只需改程序，加一个定时/计数/联锁只是几行梯形图——这是硬接线做不到的。</p><p>程序再可靠也有死机的时候，安全底线还得靠最后一章的接地、漏电与急救知识兜住。</p><h2 id="易错清单" tabindex="-1">易错清单 <a class="header-anchor" href="#易错清单" aria-label="Permalink to &quot;易错清单&quot;">​</a></h2><p>按踩坑频率排序，格式是「错误做法 → 会得到什么 → 正确做法」。</p><ol><li><strong>一个线圈在程序里出现两次</strong> → 后执行的覆盖先执行的，前面支路白写 → 线圈只出现一次，「或」逻辑并进同一条支路或用 M 中转。</li><li><strong>把梯形图当电路追电流</strong> → 分析串行覆盖现象时必然出错 → 它是逻辑运算，读成布尔等式。</li><li><strong>停止按钮硬件接常开</strong> → 断线时程序不知道，电机停不下来 → <strong>硬件接常闭</strong>，程序里当条件串联（故障导向安全）。</li><li><strong>急停只写进程序</strong> → 程序死机时急停失效 → 急停直接串在接触器线圈电源回路，不经过 PLC。</li><li><strong>TON 计时中断以为能续算</strong> → 定时值清零、动作时间对不上 → 条件断开当前值清零重来；要「断开保持」得另搭回路。</li><li><strong>响应延迟按 0 估</strong> → 高速场合（限位、急停）出错 → 按 1~2 个扫描周期估；关键信号走硬件或中断。</li><li><strong>输出类型不看</strong> → 继电器输出接高频脉冲失灵、晶体管输出接交流烧毁 → 继电器输出（交直流、慢）、晶体管输出（直流、快、可脉冲）分开选。</li></ol><h2 id="自检" tabindex="-1">自检 <a class="header-anchor" href="#自检" aria-label="Permalink to &quot;自检&quot;">​</a></h2><ol><li>为什么「输入变化后输出至少要等半个周期、至多两个周期」？用采样、执行、刷新三阶段各说一句话。</li><li>把第 19 章的正反转互锁电路翻译成两个逻辑式——自锁触点和互锁常闭触点各对应式子里哪一项？</li><li>停止按钮接常闭、程序里写常开触点，这两件事为什么合起来才是「故障导向安全」？</li></ol><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>逻辑做完了，这一页反复提到的「急停要硬接线、热继电器要后备」指向同一个主题：电的安全底线。</p><p>→ <a href="./safety">21 · 安全用电</a> —— 前面所有电路的底线</p>`,18))])}const Q=d(u,[["render",k]]);export{C as __pageData,Q as default};
